import sys, json, argparse
import numpy as np
from pathlib import Path
from rcb_client import Robot

OUT=Path('/app/output')
r=Robot()
spec=r.spec()
layout=spec['action_types']['delta']['layout']
prop=spec['proprio_layout']

def obs(tag='obs', depth=True):
    q=r.get_obs(cameras=['robot_base','robot_wrist'], include_depth=depth, video='none')
    for name,im in q.last.items():
        from PIL import Image
        Image.fromarray(im).save(OUT/f'{tag}_{name}.png')
    if depth:
        for name,d in q.depth.items(): np.save(OUT/f'{tag}_{name}_depth.npy',d)
    print(json.dumps(q.meta,default=str))
    return q

def move(rows,tag='move',depth=False):
    a=np.zeros((len(rows),len(layout)),dtype=float)
    a[:,layout.index('gripper')]=0
    for i,row in enumerate(rows):
        for k,v in row.items(): a[i,layout.index(k)]=v
    q=r.submit('delta',a,cameras=['robot_base','robot_wrist'],video='none',include_depth=depth,note=tag)
    for name,im in q.last.items():
        from PIL import Image
        Image.fromarray(im).save(OUT/f'{tag}_{name}.png')
    if depth:
        for name,d in q.depth.items(): np.save(OUT/f'{tag}_{name}_depth.npy',d)
    print(json.dumps(q.meta,default=str))
    return q

if __name__=='__main__':
    p=argparse.ArgumentParser();p.add_argument('cmd',choices=['spec','obs','status']);p.add_argument('--tag',default='obs');args=p.parse_args()
    if args.cmd=='spec':print(json.dumps(spec,indent=2))
    elif args.cmd=='status':print(json.dumps(r.status(),indent=2))
    else:obs(args.tag)
PY
